INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (10, 0, 11, 1, 20182, 0, 118011, 0, "陛下直々のご命令とあれば、\nこのクレジッタ・キャッシュ！\nご満足いただける大秘宝を、\nなんとしても手に入れてみせますわ！", 1201820008, 1);
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES ("", "", 91, "", 20182, "", 0, "", "", 1201820009, "");
